              <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 shadow-[0_0_8px_rgba(74,222,128,0.35)]" />
              Réseau actif
            </span>
            <span>{settings.address}</span>
          </div>
        </div>
      </div>
    </footer>
